import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
const clone = '/home/jack/.t3/bench-runs-lanes/thermo-213-codex/2026-10-28-thermo-nuclear-review-codex-astra/att-023/clone';
async function load(fixture, name) {
  const dir = `${clone}/packages/integrations/vercel/test/fixtures/${fixture}/.vercel/output/functions/${name}.func/`;
  const config = JSON.parse(await readFile(`${dir}.vc-config.json`, 'utf8'));
  return (await import(pathToFileURL(dir + config.handler))).default;
}
const render = await load('serverless-with-dynamic-routes', '_render');
for (const [label, headers, expected] of [
  ['query only', {}, 'public'],
  ['untrusted path header', {'x-astro-path':'/api/private'}, 'public'],
  ['ISR marker and query, no secret', {'x-vercel-isr':'1'}, 'private'],
  ['ISR marker and query, invalid secret', {'x-vercel-isr':'1', 'x-astro-middleware-secret':'invalid'}, 'private'],
]) {
  const response = await render.fetch(new Request('https://example.com/api/public?x_astro_path=/api/private', {headers}));
  const body = await response.json();
  assert.equal(body.id, expected);
  console.log(JSON.stringify({label, status:response.status, body}));
}
const isr = await load('isr', '_isr');
for (const [label, url, headers, expected] of [
  ['ISR without marker', '/_isr?x_astro_path=/one', {}, 404],
  ['ISR normal rewrite', '/_isr?x_astro_path=/one', {'x-vercel-isr':'1'}, 200],
  ['ISR excluded page target', '/_isr?x_astro_path=/two', {'x-vercel-isr':'1'}, 200],
]) {
  const response = await isr.fetch(new Request('https://example.com' + url, {headers}));
  const body = await response.text();
  assert.equal(response.status, expected);
  console.log(JSON.stringify({label, status:response.status, title:body.match(/<title>(.*?)<\/title>/)?.[1]}));
}
